- (NSInteger)collectionView:(NSCollectionView *)c numberOfItemsInSection:(NSInteger)s{return self.filtered.count;}
- (NSCollectionViewItem *)collectionView:(NSCollectionView *)c itemForRepresentedObjectAtIndexPath:(NSIndexPath *)p { ATSoundItem *i=(id)[c makeItemWithIdentifier:@"sound" forIndexPath:p];ATSound *s=self.filtered[p.item];i.titleLabel.stringValue=s.name;i.categoryLabel.stringValue=s.category.uppercaseString;i.icon.image=[NSImage imageWithSystemSymbolName:s.symbol accessibilityDescription:s.name];i.button.identifier=s.identifier;i.button.target=self;i.button.action=@selector(soundClicked:);BOOL active=[self.audio isActive:s.identifier];i.view.layer.backgroundColor=(active?[ATAccent() colorWithAlphaComponent:.2]:[NSColor controlBackgroundColor]).CGColor;i.view.layer.borderColor=(active?ATAccent():[NSColor separatorColor]).CGColor;i.icon.contentTintColor=active?ATAccent():NSColor.secondaryLabelColor;i.button.toolTip=active?[NSString stringWithFormat:@"Stop %@",s.name]:[NSString stringWithFormat:@"Play %@",s.name];return i; }
- (void)soundClicked:(NSButton *)b { ATSound *s=[self.catalog soundWithIdentifier:b.identifier];if([self.audio isActive:s.identifier])[self.audio stopSound:s.identifier];else{NSError *e;if(![self.audio startSound:s volume:.28 error:&e]){NSAlert *a=[NSAlert new];a.messageText=@"Audio is unavailable";a.informativeText=e.localizedDescription?:@"Check your audio output and try again.";[a beginSheetModalForWindow:self.window completionHandler:nil];}} }
- (void)refreshUI { [self.collection reloadData];for(NSView *v in self.mixerStack.arrangedSubviews)[self.mixerStack removeArrangedSubview:v], [v removeFromSuperview];for(NSString *sid in self.audio.activeIdentifiers){ATSound *s=[self.catalog soundWithIdentifier:sid];NSView *row=[NSView new];row.wantsLayer=YES;row.layer.cornerRadius=10;row.layer.backgroundColor=[NSColor.controlBackgroundColor colorWithAlphaComponent:.65].CGColor;row.translatesAutoresizingMaskIntoConstraints=NO;[row.heightAnchor constraintEqualToConstant:64].active=YES;[row.widthAnchor constraintEqualToAnchor:self.mixerStack.widthAnchor constant:-16].active=YES;NSTextField *name=[self label:s.name size:13 weight:NSFontWeightSemibold];[row addSubview:name];NSSlider *slider=[NSSlider sliderWithValue:[self.audio volumeForSound:sid] minValue:0 maxValue:1 target:self action:@selector(soundVolume:)];slider.identifier=sid;slider.translatesAutoresizingMaskIntoConstraints=NO;slider.toolTip=[NSString stringWithFormat:@"%@ volume",s.name];[row addSubview:slider];NSButton *mute=[NSButton buttonWithImage:[NSImage imageWithSystemSymbolName:[self.audio isMuted:sid]?@"speaker.slash.fill":@"speaker.wave.2.fill" accessibilityDescription:@"Mute"] target:self action:@selector(muteSound:)];mute.identifier=sid;mute.bordered=NO;mute.translatesAutoresizingMaskIntoConstraints=NO;[row addSubview:mute];NSButton *remove=[NSButton buttonWithImage:[NSImage imageWithSystemSymbolName:@"xmark" accessibilityDescription:@"Remove"] target:self action:@selector(removeSound:)];remove.identifier=sid;remove.bordered=NO;remove.translatesAutoresizingMaskIntoConstraints=NO;[row addSubview:remove];[NSLayoutConstraint activateConstraints:@[[name.leadingAnchor constraintEqualToAnchor:row.leadingAnchor constant:12],[name.topAnchor constraintEqualToAnchor:row.topAnchor constant:9],[slider.leadingAnchor constraintEqualToAnchor:name.leadingAnchor],[slider.trailingAnchor constraintEqualToAnchor:mute.leadingAnchor constant:-8],[slider.bottomAnchor constraintEqualToAnchor:row.bottomAnchor constant:-9],[mute.trailingAnchor constraintEqualToAnchor:remove.leadingAnchor constant:-6],[mute.centerYAnchor constraintEqualToAnchor:slider.centerYAnchor],[remove.trailingAnchor constraintEqualToAnchor:row.trailingAnchor constant:-10],[remove.centerYAnchor constraintEqualToAnchor:mute.centerYAnchor]]];[self.mixerStack addArrangedSubview:row];}NSInteger n=self.audio.activeIdentifiers.count;self.mixSubtitle.stringValue=n?[NSString stringWithFormat:@"%ld sound%@ playing",n,n==1?@"":@"s"]:@"Choose sounds to begin";self.pauseButton.title=self.audio.paused?@"Resume":@"Pause"; }
- (void)soundVolume:(NSSlider *)s{[self.audio setVolume:s.floatValue forSound:s.identifier];}- (void)muteSound:(NSButton *)b{[self.audio setMuted:![self.audio isMuted:b.identifier] forSound:b.identifier];}- (void)removeSound:(NSButton *)b{[self.audio stopSound:b.identifier];}
- (void)masterChanged:(NSSlider *)s{self.audio.masterVolume=s.floatValue;[NSUserDefaults.standardUserDefaults setFloat:s.floatValue forKey:@"ATMaster"];}- (void)togglePause:(id)x{self.audio.paused?[self.audio resumeAll]:[self.audio pauseAll];}- (void)clearMix:(id)x{[self.audio clear];}
- (void)controlTextDidChange:(NSNotification *)n{[self filterChanged:nil];}- (void)filterChanged:(id)x {NSString *q=self.search.stringValue.lowercaseString,*cat=self.categoryPopup.titleOfSelectedItem;self.filtered=[self.catalog.sounds filteredArrayUsingPredicate:[NSPredicate predicateWithBlock:^BOOL(ATSound *s,NSDictionary *b){BOOL c=[cat isEqual:@"All sounds"]||[s.category isEqual:cat];BOOL m=!q.length||[s.name.lowercaseString containsString:q]||[s.tags componentsJoinedByString:@" "].lowercaseString&&[[s.tags componentsJoinedByString:@" "].lowercaseString containsString:q];return c&&m;}]];[self.collection reloadData];}
- (NSDictionary *)currentMix{NSMutableDictionary *m=[NSMutableDictionary new];for(NSString *sid in self.audio.activeIdentifiers)m[sid]=@([self.audio volumeForSound:sid]);return m;}- (void)persistMix{[self.presets saveRecentMix:self.currentMix];}
- (void)restoreMix{[self loadMix:self.presets.recentMix];}- (void)loadMix:(NSDictionary *)mix{[self.audio clear];for(NSString *sid in mix){ATSound *s=[self.catalog soundWithIdentifier:sid];if(s)[self.audio startSound:s volume:[mix[sid] floatValue] error:nil];}}
- (void)savePreset:(id)x{NSAlert *a=[NSAlert new];a.messageText=@"Save this soundscape";a.informativeText=@"Give your mix a name.";[a addButtonWithTitle:@"Save"];[a addButtonWithTitle:@"Cancel"];NSTextField *f=[[NSTextField alloc]initWithFrame:NSMakeRect(0,0,260,24)];f.placeholderString=@"Evening focus";a.accessoryView=f;[a beginSheetModalForWindow:self.window completionHandler:^(NSModalResponse r){if(r==NSAlertFirstButtonReturn&&f.stringValue.length){[self.presets savePresetNamed:f.stringValue mix:self.currentMix];[self rebuildPresetMenu];}}];}
- (void)rebuildPresetMenu{for(NSView *v in self.window.contentView.subviews){} NSView *panel=((NSSplitView *)self.window.contentView.subviews.lastObject).arrangedSubviews.lastObject.subviews.firstObject;for(NSView *v in panel.subviews)if([v.identifier isEqual:@"presets"]){NSPopUpButton *p=(id)v;[p removeAllItems];[p addItemWithTitle:@"Open a preset…"];for(NSDictionary *d in self.presets.builtInPresets)[p addItemWithTitle:d[@"name"]];for(NSDictionary *d in self.presets.userPresets)[p addItemWithTitle:d[@"name"]];[p addItemWithTitle:@"Rename saved preset…"];[p addItemWithTitle:@"Delete saved preset…"];}}
- (void)presetChosen:(NSPopUpButton *)p{NSInteger i=p.indexOfSelectedItem-1;NSArray *all=[self.presets.builtInPresets arrayByAddingObjectsFromArray:self.presets.userPresets];if(i>=0&&i<all.count)[self loadMix:all[i][@"mix"]];else if(i==all.count)[self managePresetDeleting:NO];else if(i==all.count+1)[self managePresetDeleting:YES];[p selectItemAtIndex:0];}
- (void)managePresetDeleting:(BOOL)deleting{NSArray *saved=self.presets.userPresets;if(!saved.count){NSAlert *e=[NSAlert new];e.messageText=@"No saved presets";e.informativeText=@"Save a mix first, then you can rename or delete it.";[e beginSheetModalForWindow:self.window completionHandler:nil];return;}NSAlert *a=[NSAlert new];a.messageText=deleting?@"Delete a saved preset":@"Rename a saved preset";NSPopUpButton *choices=[[NSPopUpButton alloc]initWithFrame:NSMakeRect(0,0,260,26)];for(NSDictionary *d in saved)[choices addItemWithTitle:d[@"name"]];a.accessoryView=choices;[a addButtonWithTitle:@"Continue"];[a addButtonWithTitle:@"Cancel"];[a beginSheetModalForWindow:self.window completionHandler:^(NSModalResponse r){if(r!=NSAlertFirstButtonReturn)return;NSUInteger idx=choices.indexOfSelectedItem;if(deleting){[self.presets deletePresetAtIndex:idx];[self rebuildPresetMenu];return;}NSAlert *rename=[NSAlert new];rename.messageText=@"New preset name";NSTextField *field=[[NSTextField alloc]initWithFrame:NSMakeRect(0,0,260,24)];field.stringValue=saved[idx][@"name"];rename.accessoryView=field;[rename addButtonWithTitle:@"Rename"];[rename addButtonWithTitle:@"Cancel"];[rename beginSheetModalForWindow:self.window completionHandler:^(NSModalResponse rr){if(rr==NSAlertFirstButtonReturn&&field.stringValue.length){[self.presets renamePresetAtIndex:idx name:field.stringValue];[self rebuildPresetMenu];}}];}];}
- (void)randomize:(id)x{NSArray *sets=@[@[@"rain",@"fire",@"wind"],@[@"forest",@"birds",@"river"],@[@"ocean",@"bowls",@"pink"],@[@"train",@"rain",@"brown"],@[@"cafe",@"piano",@"rain"]];NSArray *set=sets[arc4random_uniform((uint32_t)sets.count)];NSMutableDictionary *m=[NSMutableDictionary new];for(NSUInteger i=0;i<set.count;i++)m[set[i]]=@(.12+arc4random_uniform(20)/100.0);[self loadMix:m];}
- (void)timerChosen:(NSPopUpButton *)p{NSInteger i=p.indexOfSelectedItem;if(i==6)[self.timer cancel];else if(i>0){NSArray *mins=@[@15,@30,@45,@60,@90];[self.timer startMinutes:[mins[i-1] integerValue]];[NSUserDefaults.standardUserDefaults setInteger:[mins[i-1] integerValue] forKey:@"ATTimerMinutes"];}[p selectItemAtIndex:0];}- (void)fadeChanged:(NSButton *)b{self.timer.fadeOut=b.state==NSControlStateValueOn;[NSUserDefaults.standardUserDefaults setBool:self.timer.fadeOut forKey:@"ATFade"];}
- (void)wireTimer{self.timer.fadeOut=[NSUserDefaults.standardUserDefaults boolForKey:@"ATFade"];__weak typeof(self)w=self;self.timer.tick=^(NSTimeInterval r){w.timerLabel.stringValue=r>0?[NSString stringWithFormat:@"%02ld:%02ld remaining",(long)r/60,(long)r%60]:@"";};self.timer.finished=^(BOOL fade){fade?[w.audio fadeOutOver:30 completion:^{}]:[w.audio pauseAll];};}
- (void)toggleTheme:(id)x{self.light=!self.light;[NSUserDefaults.standardUserDefaults setBool:self.light forKey:@"ATLightTheme"];[self applyAppearance];}- (void)applyAppearance{self.window.appearance=[NSAppearance appearanceNamed:self.light?NSAppearanceNameAqua:NSAppearanceNameDarkAqua];self.window.contentView.layer.backgroundColor=(self.light?[NSColor colorWithWhite:.96 alpha:1]:[NSColor colorWithRed:.045 green:.065 blue:.075 alpha:1]).CGColor;[self.collection reloadData];}
@end
